public final class FordFulkersonSolver implements MaxFlowAlgorithm {
    private final AugmentingPathFinder pathFinder;

    public FordFulkersonSolver() {
        this(new BreadthFirstAugmentingPathFinder());
    }

    public FordFulkersonSolver(AugmentingPathFinder pathFinder) {
        if (pathFinder == null) {
            throw new IllegalArgumentException("Path finder must not be null.");
        }
        this.pathFinder = pathFinder;
    }

    @Override
    public MaxFlowResult solve(FlowProblem problem) {
        ResidualNetwork residualNetwork = new ResidualNetwork(problem.network());
        int maxFlow = 0;

        while (true) {
            java.util.Optional<AugmentingPath> path = pathFinder.find(residualNetwork, problem);
            if (path.isEmpty()) {
                return new MaxFlowResult(maxFlow, residualNetwork.snapshot());
            }

            residualNetwork.augment(path.get());
            maxFlow += path.get().bottleneck();
        }
    }
}

public final class FlowProblem {
    private final FlowNetwork network;
    private final int source;
    private final int sink;

    public FlowProblem(FlowNetwork network, int source, int sink) {
        if (network == null) {
            throw new IllegalArgumentException("Network must not be null.");
        }
        if (source < 0 || source >= network.size() || sink < 0 || sink >= network.size()) {
            throw new IllegalArgumentException("Source and sink must be valid vertex indices.");
        }

        this.network = network;
        this.source = source;
        this.sink = sink;
    }

    public static FlowProblem fromCapacities(int[][] capacities, int source, int sink) {
        return new FlowProblem(new FlowNetwork(capacities), source, sink);
    }

    public FlowNetwork network() {
        return network;
    }

    public int source() {
        return source;
    }

    public int sink() {
        return sink;
    }
}

public final class FlowNetwork {
    private final int[][] capacities;

    public FlowNetwork(int[][] capacities) {
        validate(capacities);
        this.capacities = IntMatrix.copyOf(capacities);
    }

    public int size() {
        return capacities.length;
    }

    public int capacity(int from, int to) {
        return capacities[from][to];
    }

    public int[][] copyCapacities() {
        return IntMatrix.copyOf(capacities);
    }

    private static void validate(int[][] capacities) {
        if (capacities == null || capacities.length == 0) {
            throw new IllegalArgumentException("Graph must not be empty.");
        }

        int size = capacities.length;
        for (int row = 0; row < size; row++) {
            if (capacities[row] == null || capacities[row].length != size) {
                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
            }
            for (int column = 0; column < size; column++) {
                if (capacities[row][column] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative.");
                }
            }
        }
    }
}

public final class MaxFlowResult {
    private final int maxFlow;
    private final int[][] residualGraph;

    public MaxFlowResult(int maxFlow, int[][] residualGraph) {
        this.maxFlow = maxFlow;
        this.residualGraph = IntMatrix.copyOf(residualGraph);
    }

    public int getMaxFlow() {
        return maxFlow;
    }

    public int[][] copyResidualGraph() {
        return IntMatrix.copyOf(residualGraph);
    }
}

public final class ResidualNetwork {
    private final int[][] capacities;

    public ResidualNetwork(FlowNetwork network) {
        capacities = network.copyCapacities();
    }

    public int size() {
        return capacities.length;
    }

    public boolean hasCapacity(int from, int to) {
        return capacities[from][to] > 0;
    }

    public int capacity(int from, int to) {
        return capacities[from][to];
    }

    public void augment(AugmentingPath path) {
        for (int vertex = path.sink(); vertex != path.source(); vertex = path.parentOf(vertex)) {
            int previous = path.parentOf(vertex);
            capacities[previous][vertex] -= path.bottleneck();
            capacities[vertex][previous] += path.bottleneck();
        }
    }

    public int[][] snapshot() {
        return IntMatrix.copyOf(capacities);
    }
}

public final class AugmentingPath {
    private final int source;
    private final int sink;
    private final int bottleneck;
    private final int[] parents;

    public AugmentingPath(int source, int sink, int bottleneck, int[] parents) {
        this.source = source;
        this.sink = sink;
        this.bottleneck = bottleneck;
        this.parents = parents.clone();
    }

    public int source() {
        return source;
    }

    public int sink() {
        return sink;
    }

    public int bottleneck() {
        return bottleneck;
    }

    public int parentOf(int vertex) {
        return parents[vertex];
    }
}

public final class FordFulkersonMaxFlow {
    private FordFulkersonMaxFlow() {
    }

    public static void main(String[] args) {
        FlowProblem problem = FlowProblem.fromCapacities(new int[][] {
            {0, 16, 13, 0, 0, 0},
            {0, 0, 10, 12, 0, 0},
            {0, 4, 0, 0, 14, 0},
            {0, 0, 9, 0, 0, 20},
            {0, 0, 0, 7, 0, 4},
            {0, 0, 0, 0, 0, 0}
        }, 0, 5);

        MaxFlowAlgorithm algorithm = new FordFulkersonSolver();
        MaxFlowResult result = algorithm.solve(problem);

        System.out.println("The maximum possible flow is " + result.getMaxFlow());
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Optional;
import java.util.Queue;

public final class BreadthFirstAugmentingPathFinder implements AugmentingPathFinder {
    @Override
    public Optional<AugmentingPath> find(ResidualNetwork network, FlowProblem problem) {
        boolean[] visited = new boolean[network.size()];
        int[] parents = new int[network.size()];
        Queue<Integer> queue = new ArrayDeque<>();

        Arrays.fill(parents, -1);
        queue.add(problem.source());
        visited[problem.source()] = true;

        while (!queue.isEmpty()) {
            int current = queue.poll();

            for (int next = 0; next < network.size(); next++) {
                if (visited[next] || !network.hasCapacity(current, next)) {
                    continue;
                }

                parents[next] = current;
                if (next == problem.sink()) {
                    return Optional.of(createPath(network, problem, parents));
                }

                visited[next] = true;
                queue.add(next);
            }
        }

        return Optional.empty();
    }

    private AugmentingPath createPath(ResidualNetwork network, FlowProblem problem, int[] parents) {
        int bottleneck = Integer.MAX_VALUE;

        for (int vertex = problem.sink(); vertex != problem.source(); vertex = parents[vertex]) {
            int previous = parents[vertex];
            bottleneck = Math.min(bottleneck, network.capacity(previous, vertex));
        }

        return new AugmentingPath(problem.source(), problem.sink(), bottleneck, parents);
    }
}

public interface MaxFlowAlgorithm {
    MaxFlowResult solve(FlowProblem problem);
}

